45					InstanceURL: viper.GetString("instance-url"),
46				}
47				instanceProfile.Version = version.GetCurrentVersion()
48				instanceProfile.Commit = version.Commit
49				webhook.AllowPrivateIPs = viper.GetBool("allow-private-webhooks")
50	
51				if err := instanceProfile.Validate(); err != nil {
52					slog.Error("failed to validate profile", "error", err)
53					return
54				}
55	
56				ctx, cancel := context.WithCancel(context.Background())
57				dbDriver, err := db.NewDBDriver(instanceProfile)
58				if err != nil {
59					cancel()
60					slog.Error("failed to create db driver", "error", err)
61					return
62				}
63	
64				storeInstance := store.New(dbDriver, instanceProfile)
65				if err := storeInstance.Migrate(ctx); err != nil {
66					cancel()
67					slog.Error("failed to migrate", "error", err)
68					return
69				}
70				if err := storeInstance.LoadDeploymentConfiguration(ctx); err != nil {
71					cancel()
72					slog.Error("failed to load deployment configuration", "error", err)
73					return
74				}
75	
76				s, err := server.NewServer(ctx, instanceProfile, storeInstance)
77				if err != nil {
78					cancel()
79					slog.Error("failed to create server", "error", err)
80					return
81				}
82	
83				c := make(chan os.Signal, 1)
84				// Trigger graceful shutdown on SIGINT or SIGTERM.
85				// The default signal sent by the `kill` command is SIGTERM,
86				// which is taken as the graceful shutdown signal for many systems, eg., Kubernetes, Gunicorn.
87				signal.Notify(c, os.Interrupt, syscall.SIGTERM)
88	
89				if err := s.Start(ctx); err != nil {
90					if err != http.ErrServerClosed {
91						slog.Error("failed to start server", "error", err)
92						cancel()
93						return
94					}
95				}
96	
97				printGreetings(instanceProfile)
98	
99				go func() {
100					<-c
101					s.Shutdown(ctx)
102					cancel()
103				}()
104	
105				// Wait for CTRL-C.
106				<-ctx.Done()
107			},
